if(EditorApplication.isPlaying)throw new System.Exception("Edit only");var terrain=Terrain.activeTerrain;var td=terrain.terrainData;var layers=td.terrainLayers.ToList();if(layers.Count!=4)throw new System.Exception("Expected 4 layers");float RoadDistance(float x,float z){var p=new Vector2(x,z);var a=new Vector2(-17,61);var b=new Vector2(-28,95);var ab=b-a;var u=Mathf.Clamp01(Vector2.Dot(p-a,ab)/ab.sqrMagnitude);return Vector2.Distance(p,a+u*ab);}
var alpha=new float[td.alphamapHeight,td.alphamapWidth,4];int changed=0;for(int y=0;y<td.alphamapHeight;y++)for(int x=0;x<td.alphamapWidth;x++){float wx=terrain.transform.position.x+x*td.size.x/(td.alphamapWidth-1),wz=terrain.transform.position.z+y*td.size.z/(td.alphamapHeight-1);float dx=(wx+29)/21f,dz=(wz-101)/18f;float edge=Mathf.Sqrt(dx*dx+dz*dz);float wobble=.035f*Mathf.Sin(wx*.57f+wz*.19f)+.03f*Mathf.Cos(wz*.62f);float strength=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.65f,1,edge+wobble));float avoidRoad=wz<95?Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.8f,4.5f,RoadDistance(wx,wz))):1;strength*=avoidRoad*.92f;float soil=.2f+.3f*Mathf.PerlinNoise(wx*.17f+30,wz*.17f);float pebble=.5f*Mathf.Exp(-((wx+36)*(wx+36)+(wz-98)*(wz-98))/18f)+.3f*Mathf.Exp(-((wx+20)*(wx+20)+(wz-105)*(wz-105))/12f);alpha[y,x,0]=1-strength;alpha[y,x,1]=strength*(1-soil-pebble);alpha[y,x,2]=strength*soil;alpha[y,x,3]=strength*pebble;if(strength>.00001f)changed++;}
Undo.RegisterCompleteObjectUndo(td,"Environment02 limited terrain painting");td.terrainLayers=layers.ToArray();td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);AssetDatabase.SaveAssetIfDirty(td);
return changed;